import { useId, useState } from 'react';
import type { FormEvent } from 'react';

export type Reservation = { start: string; end: string; guests: number };
export type Props = {
  capacity: number;
  onReserve: (reservation: Reservation) => void;
};

type Errors = { start?: string; end?: string; guests?: string };

function validate(
  start: string,
  end: string,
  guests: string,
  capacity: number,
): Errors {
  const errors: Errors = {};
  if (!start) errors.start = 'Start date is required';
  if (!end) {
    errors.end = 'End date is required';
  } else if (start && end <= start) {
    // 入力は YYYY-MM-DD なので日付順と文字列順が一致する。
    errors.end = 'End date must be after start date';
  }

  const count = Number(guests);
  if (guests.trim() === '') {
    errors.guests = 'Guests is required';
  } else if (!Number.isInteger(count) || count < 1 || count > capacity) {
    errors.guests = `Guests must be an integer between 1 and ${capacity}`;
  }
  return errors;
}

export function Component({ capacity, onReserve }: Props) {
  const id = useId();
  const [start, setStart] = useState('');
  const [end, setEnd] = useState('');
  const [guests, setGuests] = useState('');
  const [errors, setErrors] = useState<Errors>({});

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const nextErrors = validate(start, end, guests, capacity);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) return;
    onReserve({ start, end, guests: Number(guests) });
  }

  return (
    <form aria-label="Reservation" noValidate onSubmit={submit}>
      <div>
        <label htmlFor={`${id}-start`}>Start date</label>
        <input
          id={`${id}-start`}
          type="date"
          value={start}
          required
          onChange={event => setStart(event.currentTarget.value)}
          aria-invalid={Boolean(errors.start)}
          aria-describedby={errors.start ? `${id}-start-error` : undefined}
        />
        {errors.start && (
          <p id={`${id}-start-error`} role="alert">{errors.start}</p>
        )}
      </div>
      <div>
        <label htmlFor={`${id}-end`}>End date</label>
        <input
          id={`${id}-end`}
          type="date"
          value={end}
          required
          onChange={event => setEnd(event.currentTarget.value)}
          aria-invalid={Boolean(errors.end)}
          aria-describedby={errors.end ? `${id}-end-error` : undefined}
        />
        {errors.end && (
          <p id={`${id}-end-error`} role="alert">{errors.end}</p>
        )}
      </div>
      <div>
        <label htmlFor={`${id}-guests`}>Guests</label>
        <input
          id={`${id}-guests`}
          type="number"
          value={guests}
          required
          min={1}
          max={capacity}
          step={1}
          onChange={event => setGuests(event.currentTarget.value)}
          aria-invalid={Boolean(errors.guests)}
          aria-describedby={errors.guests ? `${id}-guests-error` : undefined}
        />
        {errors.guests && (
          <p id={`${id}-guests-error`} role="alert">{errors.guests}</p>
        )}
      </div>
      <button type="submit">Reserve</button>
    </form>
  );
}
